const { status, customer, subscription, collectionMethod, createdAfter, createdBefore, limit, startingAfter } = $.input;

const params = {};
if (status) params.status = status;
if (customer) params.customer = customer;
if (subscription) params.subscription = subscription;
if (collectionMethod) params.collection_method = collectionMethod;
if (createdAfter) params['created[gte]'] = String(createdAfter);
if (createdBefore) params['created[lte]'] = String(createdBefore);
if (limit) params.limit = String(Math.max(1, Math.min(100, limit)));
if (startingAfter) params.starting_after = startingAfter;

return { params };

const resp = $.steps.listInvoices.response || {};
const invoices = resp.data || [];

const invoiceKeysToRemove = [
  'object', 'account_tax_ids', 'amount_overpaid', 'application',
  'application_fee_amount', 'attempt_count', 'attempted', 'auto_advance',
  'automatically_finalizes_at', 'charge', 'confirmation_secret',
  'custom_fields', 'customer_address', 'customer_phone', 'customer_shipping',
  'customer_tax_exempt', 'customer_tax_ids', 'default_payment_method',
  'default_source', 'default_tax_rates', 'discount', 'effective_at',
  'ending_balance', 'footer', 'from_invoice', 'last_finalization_error',
  'latest_revision', 'livemode', 'metadata', 'next_payment_attempt',
  'on_behalf_of', 'parent', 'payment_settings', 'payments',
  'post_payment_credit_notes_amount', 'pre_payment_credit_notes_amount',
  'quote', 'receipt_number', 'rendering', 'shipping_cost', 'shipping_details',
  'starting_balance', 'statement_descriptor', 'test_clock', 'threshold_reason',
  'total_pretax_credit_amounts', 'webhooks_delivered_at'
];

const lineKeysToRemove = ['object', 'livemode', 'metadata', 'parent', 'pretax_credit_amounts', 'pricing', 'taxes'];

function compressInvoice(inv) {
  const c = { ...inv };
  invoiceKeysToRemove.forEach(k => delete c[k]);

  if (c.lines && c.lines.data) {
    c.lines.data = c.lines.data.map(line => {
      const l = { ...line };
      lineKeysToRemove.forEach(k => delete l[k]);
      return l;
    });
  }

  return c;
}

const compressed = invoices.map(compressInvoice);

return {
  invoices: compressed,
  totalReturned: compressed.length,
  hasMore: resp.has_more || false,
  summary: `Retrieved ${compressed.length} invoice${compressed.length === 1 ? '' : 's'}`
};
